+// isCleanReviewVerdict reports whether every reviewer approved without
+// qualification. Combined narratives put each reviewer under a "## <name>"
+// heading, so one approving reviewer must not hide another's findings.
+func isCleanReviewVerdict(verdict string) bool {
+	sections := splitReviewerSections(verdict)
+	if len(sections) == 0 {
+		return false
+	}
+	for _, lines := range sections {
+		if !isCleanReviewerSection(lines) {
+			return false
+		}
+	}
